{"arguments":{"content":"import os, csv, json, statistics

dates = ["20191201", "20191202", "20191203"]
node_dir = os.environ["NODE_FLOW_DIR"]
station = "乌鲁木齐站"

daily = {}
read_ok = {}
for d in dates:
    path = os.path.join(node_dir, f"{d}_node.csv")
    try:
        s = 0.0
        with open(path, encoding="utf-8") as f:
            for row in csv.DictReader(f):
                if row["站名"] == station:
                    v = row["计算流量"].strip()
                    if v:
                        s += float(v)
        daily[d] = s
        read_ok[d] = True
    except Exception:
        read_ok[d] = False
        daily[d] = None

demand = {d: (max(v, 0.0) if v is not None else None) for d, v in daily.items()}
vals = [v for v in demand.values() if v is not None]
mean = sum(vals) / len(vals)
mx, mn = max(vals), min(vals)
pstd = statistics.pstdev(vals)
z = {d: ((demand[d] - mean) / pstd if pstd > 0 else 0.0) for d in dates if demand[d] is not None}
anomalous = [d for d in dates if d in z and z[d] > 2]

out = {
    "station": station,
    "read_success": read_ok,
    "daily_sum_flow": daily,
    "daily_demand": demand,
    "mean": mean, "max": mx, "min": mn,
    "population_std": pstd,
    "z_scores": z,
    "anomalous_dates_z_gt_2": anomalous,
}
print(json.dumps(out, ensure_ascii=False, indent=2))
